import asyncio
import glob
import json
import os
import sys

from dotenv import load_dotenv

# Repo root se .env load karo
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
load_dotenv(os.path.join(ROOT, ".env"))

